export enum VoiceBroadcastInfoState {
    Started = "started",
    Paused = "paused",
    Resumed = "resumed",
    Stopped = "stopped",
}

export interface VoiceBroadcastInfoEventContent {
    device_id: string;
    state: VoiceBroadcastInfoState;
    chunk_length?: number;
    last_chunk_sequence?: number;
    ["m.relates_to"]?: {
        rel_type: RelationType;
        event_id: string;
    };
}

